import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import { supabase } from "./supabaseClient";
import LoginForm from "./components/LoginForm";
import Dashboard from "./components/Dashboard";
import Logs from "./components/Logs";
import Analytics from "./components/Analytics";

function App() {
  const [isAdmin, setIsAdmin] = useState(false);

  // Optional: persist login session
  useEffect(() => {
    const session = supabase.auth.getSession().then(({ data }) => {
      if (data.session) {
        setIsAdmin(true);
      }
    });
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setIsAdmin(false);
  };

  return (
    <Router>
      <nav style={{ padding: "10px", borderBottom: "1px solid #ccc" }}>
        {isAdmin ? (
          <>
            <Link to="/dashboard" style={{ marginRight: "15px" }}>Dashboard</Link>
            <Link to="/logs" style={{ marginRight: "15px" }}>Logs</Link>
            <Link to="/analytics" style={{ marginRight: "15px" }}>Analytics</Link>
            <button onClick={handleLogout}>Logout</button>
          </>
        ) : (
          <LoginForm setIsAdmin={setIsAdmin} />
        )}
      </nav>

      <Routes>
        {isAdmin && (
          <>
            <Route path="/dashboard" element={<Dashboard />} />
            <Route path="/logs" element={<Logs />} />
            <Route path="/analytics" element={<Analytics />} />
          </>
        )}
        <Route path="*" element={<p>Welcome! Please login as admin.</p>} />
      </Routes>
    </Router>
  );
}

export default App;
